package local.atmospherevisual;
import me.cryo.zombierool.gameplay.*;
import me.cryo.zombierool.client.gui.ParticlePickerScreen;
import net.minecraft.client.Minecraft;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.fml.common.Mod;
@Mod("atmospherevisual")
public final class PortableTurretVisualTest {
 boolean requested,done;int age,checks;volatile String failure;final BlockPos pos=new BlockPos(0,73,28);
 public PortableTurretVisualTest(){MinecraftForge.EVENT_BUS.addListener(this::tick);}
 void check(boolean v,String label){if(!v)throw new AssertionError(label);checks++;System.out.println("ATMOSPHERE VISUAL CHECK: "+label);}
 void server(java.util.function.Consumer<net.minecraft.server.level.ServerPlayer> action){var mc=Minecraft.getInstance();mc.getSingleplayerServer().execute(()->{try{action.accept(mc.getSingleplayerServer().getPlayerList().getPlayers().get(0));}catch(Throwable t){failure=t.toString();t.printStackTrace();}});}
 void hurt(PortableEquipment.Device d){try{var method=PortableEquipment.Device.class.getDeclaredMethod("damage",int.class);method.setAccessible(true);method.invoke(d,10);}catch(Exception ex){throw new RuntimeException(ex);}}
 void shot(String name)throws Exception{try(var image=net.minecraft.client.Screenshot.takeScreenshot(Minecraft.getInstance().getMainRenderTarget())){if(image.getWidth()<640)throw new AssertionError("Invalid capture size");image.writeToFile(java.nio.file.Path.of(System.getProperty("atmosphere.output"),name+".png"));}}
 void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;try{
  if(failure!=null)throw new AssertionError(failure);
  if(!requested){requested=true;mc.options.pauseOnLostFocus=false;org.lwjgl.glfw.GLFW.glfwHideWindow(mc.getWindow().getWindow());mc.createWorldOpenFlows().loadLevel(mc.screen,"AtmosphereFixture");return;}
  if(mc.level==null||mc.player==null||mc.isPaused())return;if(mc.getMainRenderTarget().width<640){mc.getWindow().setWidth(1280);mc.getWindow().setHeight(720);mc.resizeDisplay();}age++;
  if(age==20){mc.options.hideGui=true;mc.options.fov().set(50);server(p->{var l=p.serverLevel();MapAtmosphere.get(l).configure(l,MapAtmosphere.defaults());p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);for(var at:BlockPos.betweenClosed(-4,72,24,4,77,34))l.setBlock(at,at.getY()==72?net.minecraft.world.level.block.Blocks.STONE.defaultBlockState():net.minecraft.world.level.block.Blocks.AIR.defaultBlockState(),3);p.teleportTo(l,2,73,31.5,150,14);l.setBlock(pos,PortableEquipment.SENTRY_BLOCK.get().defaultBlockState(),3);var d=(PortableEquipment.Device)l.getBlockEntity(pos);var n=d.saveWithoutMetadata();n.put("stack",new ItemStack(PortableEquipment.SENTRY.get()).save(new net.minecraft.nbt.CompoundTag()));n.putFloat("aimYaw",0);d.load(n);l.sendBlockUpdated(pos,d.getBlockState(),d.getBlockState(),3);});}
  if(age==50){var model=mc.getItemRenderer().getModel(new ItemStack(PortableEquipment.SENTRY.get()),mc.level,null,0);check(model!=mc.getModelManager().getMissingModel(),"Minecraft sentry model bakes successfully");int faces=model.getQuads(null,null,net.minecraft.util.RandomSource.create()).size();check(faces>1000&&faces<70000,"Intermediate sentry retains the original silhouette with fewer than 70000 faces: "+faces);check(model.getQuads(null,null,net.minecraft.util.RandomSource.create()).stream().noneMatch(q->q.getSprite().contents().name().getPath().contains("missingno")),"Every sentry material resolves to an actual atlas texture");me.cryo.zombierool.client.WallModelIconCache.get(new ItemStack(PortableEquipment.SENTRY.get()),model,net.minecraft.world.item.ItemDisplayContext.GUI);shot("sentry-deployed");}
  if(age==55)server(p->{var d=(PortableEquipment.Device)p.serverLevel().getBlockEntity(pos);var n=d.saveWithoutMetadata();n.putFloat("aimYaw",60);n.putFloat("aimPitch",25);d.load(n);hurt(d);p.serverLevel().sendBlockUpdated(pos,d.getBlockState(),d.getBlockState(),3);});
  if(age==58){check(mc.level.getBlockEntity(pos) instanceof PortableEquipment.Device d&&d.damageFlash(0)>0,"Real turret damage synchronizes its visible impact flash");shot("sentry-damaged");}
  if(age==65)shot("sentry-aiming");
  if(age==70){check(ParticlePickerScreen.choices(false,"cl").contains("minecraft:cloud"),"Typing cl keeps the cloud search result");var vanilla=ParticlePickerScreen.choices(false,"");var mods=ParticlePickerScreen.choices(true,"");check(vanilla.contains("minecraft:smoke")&&vanilla.stream().allMatch(id->id.startsWith("minecraft:")),"Vanilla particle category uses registered usable particles");check(!mods.isEmpty()&&mods.stream().noneMatch(id->id.startsWith("minecraft:")),"Mods category includes installed mod particles");check(ParticlePickerScreen.choices(false,"smoke").stream().allMatch(id->id.contains("smoke")),"Particle search filters the list");mc.options.hideGui=false;mc.setScreen(new ParticlePickerScreen(null,"minecraft:smoke",id->{}));}
  if(age==73){var field=ParticlePickerScreen.class.getDeclaredField("list");field.setAccessible(true);var list=(net.minecraft.client.gui.components.AbstractSelectionList<?>)field.get(mc.screen);list.setScrollAmount(10000);for(var child:mc.screen.children())if(child instanceof net.minecraft.client.gui.components.EditBox box)box.setValue("cl");check(list.getScrollAmount()==0,"Filtering a scrolled particle list resets to visible results");}
  if(age==75)shot("particles-vanilla");
  if(age==80){for(var child:mc.screen.children())if(child instanceof net.minecraft.client.gui.components.EditBox box)box.setValue("");for(var child:java.util.List.copyOf(mc.screen.children()))if(child instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().equals("Mods")){b.onPress();break;}}
  if(age==85){shot("particles-mods");mc.screen.onClose();mc.options.hideGui=true;mc.options.fov().set(50);server(p->{var d=(PortableEquipment.Device)p.serverLevel().getBlockEntity(pos);var n=d.saveWithoutMetadata();n.putLong("deathTick",p.serverLevel().getGameTime());n.put("stack",new ItemStack(PortableEquipment.SENTRY.get()).save(new net.minecraft.nbt.CompoundTag()));d.load(n);p.serverLevel().sendBlockUpdated(pos,d.getBlockState(),d.getBlockState(),3);});}
  if(age==96){check(mc.level.getBlockEntity(pos) instanceof PortableEquipment.Device d&&d.dying(),"Turret death state reaches the client before disappearance");shot("sentry-dying-head-down");}
  if(age==112){check(!mc.level.getBlockState(pos).is(PortableEquipment.SENTRY_BLOCK.get()),"Turret disappears after its head-lowering animation");
   var column=new BlockPos(0,95,30);mc.level.setBlock(column,me.cryo.zombierool.init.ZombieroolModBlocks.PATH.get().defaultBlockState(),3);mc.level.setBlock(column.below(),me.cryo.zombierool.init.ZombieroolModBlocks.RESTRICT.get().defaultBlockState(),3);check(me.cryo.zombierool.client.AmbientParticles.visibleHeight(mc.level,0,30)==73,"Path and restrict markers do not become an ambient-particle roof");
   server(p->{PortableEquipment.acquire(p,new ItemStack(PortableEquipment.SENTRY.get()));PortableEquipment.toggle(p);p.teleportTo(p.serverLevel(),.5,73,29.5,180,80);});}
  if(age==124){check(PortableEquipment.inHands(mc.player),"Turret preview equips through normal equipment synchronization");shot("sentry-preview-inside");check(org.lwjgl.opengl.GL11.glGetError()==0,"Close turret preview produces no OpenGL error");server(p->p.teleportTo(p.serverLevel(),2,73,31.5,150,35));}
  if(age==138){shot("sentry-preview");check(org.lwjgl.opengl.GL11.glGetError()==0,"Visible turret preview produces no OpenGL error");server(p->{PortableEquipment.clearEquipment(p);var wall=new BlockPos(0,74,28);p.serverLevel().setBlock(pos,net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),3);p.serverLevel().setBlock(wall,me.cryo.zombierool.block.system.BuyWallWeaponSystem.BLOCK.get().defaultBlockState().setValue(me.cryo.zombierool.block.system.BuyWallWeaponSystem.BuyWallWeaponBlock.FACING,net.minecraft.core.Direction.SOUTH),3);var be=(me.cryo.zombierool.block.system.BuyWallWeaponSystem.BuyWallWeaponBlockEntity)p.serverLevel().getBlockEntity(wall);be.setItemToSell(PortableEquipment.SENTRY.getId());p.serverLevel().sendBlockUpdated(wall,be.getBlockState(),be.getBlockState(),3);p.teleportTo(p.serverLevel(),.5,73,31.5,180,-5);});}
  if(age==160){check(mc.level.getBlockEntity(new BlockPos(0,74,28)) instanceof me.cryo.zombierool.block.system.BuyWallWeaponSystem.BuyWallWeaponBlockEntity be&&be.getItemToSell().equals(PortableEquipment.SENTRY.getId()),"Sentry turret reaches the actual wall weapon renderer");var wallModel=mc.getItemRenderer().getModel(new ItemStack(PortableEquipment.SENTRY.get()),mc.level,null,0);var wallIcon=me.cryo.zombierool.client.WallModelIconCache.get(new ItemStack(PortableEquipment.SENTRY.get()),wallModel,net.minecraft.world.item.ItemDisplayContext.GUI);check(wallIcon!=null,"Sentry wall drawing is baked once and available from the bounded icon cache");var chalk=((net.minecraft.client.renderer.texture.DynamicTexture)mc.getTextureManager().getTexture(wallIcon.chalk())).getPixels();int opaque=0;for(int y=0;y<chalk.getHeight();y++)for(int x=0;x<chalk.getWidth();x++)if((chalk.getPixelRGBA(x,y)>>>24)>128)opaque++;check(opaque>100&&opaque<chalk.getWidth()*chalk.getHeight()*.85,"Cached sentry chalk retains its silhouette and transparent background instead of a square");shot("sentry-wall-chalk");check(org.lwjgl.opengl.GL11.glGetError()==0,"Sentry model silhouette on the wall produces no OpenGL error");var tag=new net.minecraft.nbt.CompoundTag();tag.put("presets",me.cryo.zombierool.api.BuildablePresets.catalog());var screen=new me.cryo.zombierool.client.gui.BuildableScreen(tag);for(String name:java.util.List.of("presetsOpen","presetPage")){var field=screen.getClass().getDeclaredField(name);field.setAccessible(true);if(name.equals("presetsOpen"))field.setBoolean(screen,true);else field.setInt(screen,0);}mc.options.hideGui=false;mc.setScreen(screen);}
  if(age==165){check(mc.screen.children().stream().anyMatch(c->c instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().contains("Sentry Turret")),"Bench library displays the selectable Sentry Turret preset");shot("sentry-bench-preset");done=true;System.out.println("ATMOSPHERE VISUAL PASS: "+checks+" turret and particle picker checks");mc.stop();}
 }catch(Throwable t){t.printStackTrace();done=true;System.out.println("ATMOSPHERE VISUAL FAIL: "+t);mc.stop();}}
}
